from dateutil import parser

def parse_dt(s):
    try:
        return parser.isoparse(s)
    except Exception:
        # fallback simple
        try:
            return datetime.fromisoformat(s)
        except Exception:
            return None

matching=[]
for t in feed:
    dt=parse_dt(t.get('created_at'))
    if not dt:
        continue
    if dt.date()!=today and dt.date()!=yesterday:
        continue
    sender_email=(t.get('sender') or {}).get('email')
    receiver_email=(t.get('receiver') or {}).get('email')
    if sender_email in coworker_venmo_emails or receiver_email in coworker_venmo_emails:
        matching.append(t)

matching_ids=[m['transaction_id'] for m in matching]
